{"query": "mutation {
  bulkOperationRunQuery(
    query: """
    {
      collections(query: "updated_at:>='2024-01-01' AND updated_at:<'2025-01-01'") {
        edges {
          node {
            id
            title
            handle
            descriptionHtml
            sortOrder
            templateSuffix
            updatedAt
            productsCount {
              count
            }
            ruleSet {
              appliedDisjunctively
              rules {
                column
                condition
                relation
              }
            }
            products {
              edges {
                node {
                  id
                }
              }
            }
          }
        }
      }
    }
    """
  ) {
    bulkOperation {
      id
      status
    }
    userErrors {
      field
      message
    }
  }
}
", "variables": null, "operationName": null}

{"query": "query {
  currentBulkOperation {
    id
    status
    errorCode
    createdAt
    completedAt
    objectCount
    fileSize
    url
    partialDataUrl
  }
}
", "variables": null, "operationName": null}

